import mongoose from 'mongoose';
import User from '../models/User.js';

const connectDB = async () => {
  try {
    const conn = await mongoose.connect(process.env.MONGO_URI || 'mongodb://127.0.0.1:27017/ats-tracker', {
      // modern mongoose doesn't need useNewUrlParser or useUnifiedTopology
    });
    console.log(`MongoDB Connected: ${conn.connection.host}`);

    // Fix for E11000 duplicate key error on googleId: null
    // 1. Clean up existing corrupted data where googleId was incorrectly saved as null
    await User.collection.updateMany(
      { googleId: null },
      { $unset: { googleId: 1 } }
    );

    // 2. This forces MongoDB to drop the old non-sparse index and rebuild it as sparse.
    await User.syncIndexes();
    console.log(`User collection indexes synchronized successfully.`);
  } catch (error) {
    console.error(`Error connecting to MongoDB: ${error.message}`);
    process.exit(1);
  }
};

export default connectDB;

import ResumeAnalysis from '../models/ResumeAnalysis.js';
import { parseResume } from '../services/parser.js';
import { analyzeWithGemini } from '../services/geminiAnalyzer.js';

export const analyzeResume = async (req, res) => {
  console.log('\n========== NEW ANALYSIS ==========');
  console.time('Total Analysis');

  try {
    console.log('[1] Analysis request received');

    const file = req.file;
    const { jobDescription } = req.body;
    const userId = req.user.id;

    if (!file) {
      console.log('[X] No file uploaded');
      console.timeEnd('Total Analysis');

      return res.status(400).json({
        success: false,
        error: 'No file uploaded'
      });
    }

    console.log(`[2] File received: ${file.originalname}`);

    // 1. Extract text from resume
    console.log('[3] Parsing resume...');
    console.time('Resume Parsing');

    const text = await parseResume(file);

    console.timeEnd('Resume Parsing');
    console.log(`[4] Resume parsed successfully (${text.length} characters)`);

    // 2. Gemini Analysis
    console.log('[5] Sending request to Gemini...');
    console.time('Gemini Analysis');

    const geminiResult = await analyzeWithGemini(text, jobDescription);

    console.timeEnd('Gemini Analysis');
    console.log('[6] Gemini analysis completed successfully');

    // 3. Save to MongoDB
    console.log('[7] Saving analysis to MongoDB...');

    const newAnalysis = new ResumeAnalysis({
      userId,
      fileName: file.originalname,
      analysisSource: 'ai',
      aiModel: geminiResult.aiModel,
      analysisVersion: geminiResult.analysisVersion,
      ...geminiResult
    });

    await newAnalysis.save();

    console.log('[8] Analysis saved successfully');

    console.timeEnd('Total Analysis');
    console.log('[9] Response sent to frontend');

    return res.status(200).json({
      success: true,
      _id: newAnalysis._id,
      analysisSource: 'ai',
      ...geminiResult
    });

  } catch (error) {
    console.timeEnd('Total Analysis');

    console.error('\n[X] AI ANALYSIS FAILED');
    console.error(error);

    return res.status(500).json({
      success: false,
      error: 'AI analysis failed. Please try again.'
    });
  }
};

export const getAnalysis = async (req, res) => {
  try {
    console.log(`[GET] Fetching analysis: ${req.params.id}`);

    const analysis = await ResumeAnalysis.findById(req.params.id);

    if (!analysis) {
      console.log('[GET] Analysis not found');

      return res.status(404).json({
        message: 'Analysis not found'
      });
    }

    if (analysis.userId.toString() !== req.user.id) {
      console.log('[GET] Unauthorized access attempt');

      return res.status(403).json({
        message: 'Not authorized to view this analysis'
      });
    }

    console.log('[GET] Analysis returned successfully');

    return res.status(200).json(analysis);

  } catch (error) {
    console.error('[GET] Error fetching analysis:', error);

    return res.status(500).json({
      message: 'Error fetching analysis'
    });
  }
};

import { OAuth2Client } from 'google-auth-library';
import jwt from 'jsonwebtoken';
import User from '../models/User.js';

const client = new OAuth2Client(process.env.GOOGLE_CLIENT_ID);

export const googleAuth = async (req, res) => {
  const { credential } = req.body;
  let ticket;

  // 1. Verify Google Token
  try {
    ticket = await client.verifyIdToken({
      idToken: credential,
      audience: process.env.GOOGLE_CLIENT_ID,
    });
  } catch (error) {
    console.error('[Auth Error] Google token verification failed. Check GOOGLE_CLIENT_ID and token validity.');
    return res.status(401).json({ message: 'Google authentication rejected the token.' });
  }

  const payload = ticket.getPayload();
  const { sub: googleId, name, email, picture: profilePicture } = payload;
  let user;

  // 2. Database Operations
  try {
    user = await User.findOne({ email });
    if (user) {
      // Link Google account to existing user (e.g. from Email OTP)
      let updated = false;
      if (!user.googleId) { user.googleId = googleId; updated = true; }
      if (!user.authProviders.includes('google')) { user.authProviders.push('google'); updated = true; }
      if (!user.profilePicture && profilePicture) { user.profilePicture = profilePicture; updated = true; }
      if (updated) await user.save();
    } else {
      user = await User.create({ 
        googleId, 
        name, 
        email, 
        profilePicture,
        emailVerified: true,
        authProviders: ['google']
      });
    }
  } catch (dbError) {
    console.error('[DB Error] Failed to find or create user.', dbError);
    return res.status(500).json({ message: 'Database error during authentication.' });
  }

  // 3. Cookie Creation
  try {
    const token = jwt.sign({ id: user._id }, process.env.JWT_SECRET, { expiresIn: '7d' });

    const isProduction = process.env.NODE_ENV === 'production';
    res.cookie('token', token, {
      httpOnly: true,
      secure: isProduction,
      sameSite: isProduction ? 'none' : 'lax', // 'none' required for cross-origin HTTPS
      maxAge: 7 * 24 * 60 * 60 * 1000 // 7 days
    });

    res.status(200).json({ user: { _id: user._id, name: user.name, email: user.email, profilePicture: user.profilePicture } });
  } catch (cookieError) {
    console.error('[Auth Error] Failed to generate JWT or set cookie.');
    res.status(500).json({ message: 'Internal server error while setting up session.' });
  }
};

export const verifyToken = (req, res, next) => {
  // Check cookie first, fallback to Auth header if needed (for mobile apps or similar)
  const token = req.cookies.token || (req.headers.authorization?.split(' ')[1]);
  if (!token) return res.status(401).json({ message: 'Unauthorized' });

  try {
    const decoded = jwt.verify(token, process.env.JWT_SECRET);
    req.user = decoded;
    next();
  } catch (error) {
    res.status(401).json({ message: 'Invalid token' });
  }
};

export const getMe = async (req, res) => {
  try {
    const user = await User.findById(req.user.id).select('-__v');
    if (!user) {
      return res.status(404).json({ message: 'User not found' });
    }
    res.status(200).json(user);
  } catch (error) {
    res.status(500).json({ message: 'Server error' });
  }
};

export const logout = (req, res) => {
  res.clearCookie('token', {
    httpOnly: true,
    secure: process.env.NODE_ENV === 'production',
    sameSite: process.env.NODE_ENV === 'production' ? 'none' : 'lax',
  });
  res.status(200).json({ message: 'Logged out successfully' });
};

import ResumeAnalysis from '../models/ResumeAnalysis.js';

import User from '../models/User.js';

export const getDashboardHistory = async (req, res) => {
  try {
    const userId = req.user.id; // from verifyToken

    // 1. Fetch user profile
    const userProfile = await User.findById(userId).select('-__v');

    if (!userProfile) {
      return res.status(404).json({ message: 'User not found' });
    }

    // 2. Fetch history
    const analyses = await ResumeAnalysis.find({ userId })
      .sort({ uploadDate: -1 })
      .select('fileName uploadDate overallScore'); // Only fetch needed fields for list

    // 3. Calculate metrics
    const resumesAnalyzed = analyses.length;
    let latestScore = 0;
    let averageScore = 0;
    let bestScore = 0;

    if (resumesAnalyzed > 0) {
      latestScore = analyses[0].overallScore;

      const totalScore = analyses.reduce((sum, item) => sum + item.overallScore, 0);
      averageScore = Math.round(totalScore / resumesAnalyzed);

      bestScore = Math.max(...analyses.map(item => item.overallScore));
    }

    // 4. Return combined response
    res.status(200).json({
      profile: userProfile,
      metrics: {
        latestScore,
        averageScore,
        bestScore
      },
      history: analyses
    });
  } catch (error) {
    console.error('Error fetching dashboard data:', error);
    res.status(500).json({ message: 'Error fetching dashboard data' });
  }
};

import User from '../models/User.js';

// Get current user profile
export const getProfile = async (req, res) => {
  try {
    const userId = req.user.id;
    const user = await User.findById(userId).select('-__v');

    if (!user) {
      return res.status(404).json({ message: 'User not found' });
    }

    res.status(200).json(user);
  } catch (error) {
    console.error('Error fetching profile:', error);
    res.status(500).json({ message: 'Error fetching profile' });
  }
};

// Update user profile
export const updateProfile = async (req, res) => {
  try {
    const userId = req.user.id;
    const updateData = req.body;

    // Check if mandatory fields are present
    const mandatoryFields = ['name', 'collegeName', 'currentStatus', 'currentRole', 'graduationYear', 'location'];
    let isComplete = true;

    for (const field of mandatoryFields) {
      if (!updateData[field] || updateData[field].trim() === '') {
        isComplete = false;
        break;
      }
    }

    updateData.profileCompleted = isComplete;

    const updatedUser = await User.findByIdAndUpdate(
      userId,
      { $set: updateData },
      { new: true, runValidators: true }
    ).select('-__v');

    if (!updatedUser) {
      return res.status(404).json({ message: 'User not found' });
    }

    res.status(200).json(updatedUser);
  } catch (error) {
    console.error('Error updating profile:', error);
    res.status(500).json({ message: 'Error updating profile', error: error.message });
  }
};

import ResumeDraft from '../models/ResumeDraft.js';

// Get all drafts for user
export const getDrafts = async (req, res) => {
  try {
    const drafts = await ResumeDraft.find({ userId: req.user.id })
      .sort({ updatedAt: -1 });
    res.status(200).json(drafts);
  } catch (error) {
    console.error('Error fetching drafts:', error);
    res.status(500).json({ message: 'Error fetching drafts' });
  }
};

// Get specific draft
export const getDraft = async (req, res) => {
  try {
    const draft = await ResumeDraft.findOne({
      _id: req.params.id,
      userId: req.user.id
    });
    if (!draft) {
      return res.status(404).json({ message: 'Draft not found' });
    }
    res.status(200).json(draft);
  } catch (error) {
    console.error('Error fetching draft:', error);
    res.status(500).json({ message: 'Error fetching draft' });
  }
};

// Create new draft
export const createDraft = async (req, res) => {
  try {
    const { title, resumeData, isDefault } = req.body;

    // If setting as default, unset others
    if (isDefault) {
      await ResumeDraft.updateMany({ userId: req.user.id }, { isDefault: false });
    }

    const draft = new ResumeDraft({
      userId: req.user.id,
      title: title || 'Untitled Draft',
      resumeData,
      isDefault: isDefault || false
    });

    await draft.save();
    res.status(201).json(draft);
  } catch (error) {
    console.error('Error creating draft:', error);
    res.status(500).json({ message: 'Error creating draft' });
  }
};

// Update draft
export const updateDraft = async (req, res) => {
  try {
    const { title, resumeData, isDefault } = req.body;

    const draft = await ResumeDraft.findOne({ _id: req.params.id, userId: req.user.id });
    if (!draft) {
      return res.status(404).json({ message: 'Draft not found' });
    }

    // If setting as default, unset others
    if (isDefault && !draft.isDefault) {
      await ResumeDraft.updateMany({ userId: req.user.id }, { isDefault: false });
    }

    if (title) draft.title = title;
    if (resumeData) draft.resumeData = resumeData;
    if (isDefault !== undefined) draft.isDefault = isDefault;

    await draft.save();
    res.status(200).json(draft);
  } catch (error) {
    console.error('Error updating draft:', error);
    res.status(500).json({ message: 'Error updating draft' });
  }
};

// Delete draft
export const deleteDraft = async (req, res) => {
  try {
    const draft = await ResumeDraft.findOneAndDelete({
      _id: req.params.id,
      userId: req.user.id
    });
    if (!draft) {
      return res.status(404).json({ message: 'Draft not found' });
    }
    res.status(200).json({ message: 'Draft deleted successfully' });
  } catch (error) {
    console.error('Error deleting draft:', error);
    res.status(500).json({ message: 'Error deleting draft' });
  }
};

