import 'dotenv/config';
import mongoose from 'mongoose';
import User from './models/User.js';

async function debugDB() {
  try {
    console.log('Connecting to DB...');
    await mongoose.connect(process.env.MONGO_URI);
    console.log('Connected!');

    // Get all indexes
    const indexes = await User.collection.indexes();
    console.log('Current User Indexes:', JSON.stringify(indexes, null, 2));

    // Try creating a test user without googleId
    console.log('Trying to create test user 1...');
    await User.deleteMany({ email: 'debugtest1@example.com' });
    await User.create({
      email: 'debugtest1@example.com',
      name: 'Debug Test 1',
      authProviders: ['emailOtp']
    });
    console.log('Test user 1 created successfully.');

    // Try creating a second test user without googleId
    console.log('Trying to create test user 2...');
    await User.deleteMany({ email: 'debugtest2@example.com' });
    await User.create({
      email: 'debugtest2@example.com',
      name: 'Debug Test 2',
      authProviders: ['emailOtp']
    });
    console.log('Test user 2 created successfully.');

    // Clean up
    await User.deleteMany({ email: { $in: ['debugtest1@example.com', 'debugtest2@example.com'] } });
    console.log('Cleanup done. No duplicate key errors!');

  } catch (err) {
    console.error('DEBUG ERROR:', err);
  } finally {
    await mongoose.disconnect();
    process.exit(0);
  }
}

debugDB();

import 'dotenv/config';
import { GoogleGenAI } from '@google/genai';

async function listModels() {
  try {
    const ai = new GoogleGenAI({ apiKey: process.env.GEMINI_API_KEY });

    // According to SDK docs, we can list models using ai.models.list()
    // However, some versions use ai.models.listModels()
    // We will fetch and just log them
    const response = await fetch(`https://generativelanguage.googleapis.com/v1beta/models?key=${process.env.GEMINI_API_KEY}`);
    const data = await response.json();

    console.log("AVAILABLE MODELS:");
    data.models.forEach(m => {
      if (m.name.includes("gemini") && m.supportedGenerationMethods.includes("generateContent")) {
        console.log(`- ${m.name}`);
      }
    });
  } catch (err) {
    console.error("Error fetching models:", err);
  }
}

listModels();

import mongoose from 'mongoose';

const resumeAnalysisSchema = new mongoose.Schema({
  userId: {
    type: mongoose.Schema.Types.ObjectId,
    ref: 'User',
    required: true
  },
  fileName: {
    type: String,
    required: true
  },
  uploadDate: {
    type: Date,
    default: Date.now
  },
  // New fields for AI analysis
  analysisType: { type: String, enum: ['application_match', 'general', 'fallback'], default: 'fallback' },
  summary: { type: String },
  sectionScores: {
    contact: { type: Number, default: 0 },
    experience: { type: Number, default: 0 },
    skills: { type: Number, default: 0 },
    education: { type: Number, default: 0 },
    projects: { type: Number, default: 0 },
    writingImpact: { type: Number, default: 0 },
    atsReadability: { type: Number, default: 0 }
  },
  strengths: [{
    title: String,
    evidence: String
  }],
  problems: [{
    title: String,
    severity: String,
    evidence: String,
    recommendation: String
  }],
  matchedKeywords: [{
    name: String,
    evidence: String
  }],
  missingKeywords: [{
    name: String
  }],
  recommendedRoles: [{
    role: String,
    match: Number,
    reason: String
  }],
  bulletRewrites: [{
    original: String,
    suggested: String,
    reason: String
  }],
  disclaimer: { type: String },

  // Metadata
  analysisSource: { type: String, enum: ['ai', 'fallback', 'failed'], default: 'fallback' },
  aiModel: { type: String },
  analysisVersion: { type: String },

  // Legacy fallback fields for backward compatibility
  overallScore: { type: Number, required: true },
  suggestions: [String],
  keyObservations: [String]
});

// Index for efficient dashboard queries
resumeAnalysisSchema.index({ userId: 1, uploadDate: -1 });

const ResumeAnalysis = mongoose.model('ResumeAnalysis', resumeAnalysisSchema);
export default ResumeAnalysis;

import mongoose from 'mongoose';

const resumeDraftSchema = new mongoose.Schema({
  userId: {
    type: mongoose.Schema.Types.ObjectId,
    ref: 'User',
    required: true
  },
  resumeData: {
    type: Object,
    required: true
  },
  title: {
    type: String,
    default: 'Untitled Draft'
  },
  isDefault: {
    type: Boolean,
    default: false
  }
}, {
  timestamps: true
});

// Index for efficient querying by user and sorting by recency
resumeDraftSchema.index({ userId: 1, updatedAt: -1 });

const ResumeDraft = mongoose.model('ResumeDraft', resumeDraftSchema);
export default ResumeDraft;

import mongoose from 'mongoose';

const userSchema = new mongoose.Schema({
  googleId: { type: String, sparse: true, unique: true },
  name: { type: String, required: true },
  email: { type: String, required: true, unique: true },
  emailVerified: { type: Boolean, default: false },
  authProviders: { type: [String], default: [] },
  profilePicture: { type: String },
  collegeName: { type: String },
  degree: { type: String },
  major: { type: String },
  currentStatus: { 
    type: String, 
    enum: ['Student', 'Job Seeker', 'Working Professional', 'Other'] 
  },
  currentRole: { type: String },
  targetRole: { type: String },
  graduationYear: { type: String },
  location: { type: String },
  bio: { type: String },
  linkedin: { type: String },
  github: { type: String },
  portfolio: { type: String },
  profileCompleted: { type: Boolean, default: false }
}, {
  timestamps: true
});

const User = mongoose.model('User', userSchema);
export default User;

