*{
    margin:0;
    padding:0;
    box-sizing:border-box;
}

body{
    font-family:Segoe UI,Arial,sans-serif;
    background:#0b1220;
    color:white;
    line-height:1.8;
}

.hero{
    position:relative;
    height:300px;
    display:flex;
    justify-content:center;
    align-items:center;
    text-align:center;
    /* background:linear-gradient(135deg,#0f172a,#1e3a8a,#2563eb); */
    overflow:hidden;
}

.hero-content{
    position:relative;
    width:100%;
    padding:20px;
    z-index:2;
}

.overlay{
    position:absolute;
    inset:0;
    background:rgba(248, 242, 242, 0.45);
}

.hero h1{
    font-size:3.5rem;
    margin-bottom:20px;
}

.hero p{
    font-size:1.25rem;
    color:#dbeafe;
}

.container{
    width:90%;
    max-width:1200px;
    margin:auto;
    padding:70px 0;
}

.card{
    background:#4365a5;
    margin-bottom:35px;
    padding:35px;
    border-radius:18px;
    box-shadow:0 15px 35px rgba(0,0,0,.35);
    transition:.35s;
}

.card:hover{
    transform:translateY(-8px);
}

.card h2{
    color:#60a5fa;
    margin-bottom:20px;
}

.card p{
    margin-bottom:15px;
}

.steps{
    display:flex;
    flex-direction:column;
    gap:25px;
}

.step{
    display:flex;
    gap:20px;
}

.step span{
    width:55px;
    height:55px;
    border-radius:50%;
    background:#2563eb;
    display:flex;
    justify-content:center;
    align-items:center;
    font-size:22px;
