import { useState, useEffect } from "react";
import { Link, useNavigate } from "react-router-dom";
import { GoogleLogin } from "@react-oauth/google";
import { Menu, X } from "lucide-react";
import { useAuth } from "../../lib/AuthContext";
import "./Navbar.css";
import logo from "../../assets/logo.png";

function Navbar() {
  const { user, login, logout } = useAuth();
  const navigate = useNavigate();
  const [isMenuOpen, setIsMenuOpen] = useState(false);
  const [isScrolled, setIsScrolled] = useState(false);

  useEffect(() => {
    const handleScroll = () => {
      if (window.scrollY > 20) {
        setIsScrolled(true);
      } else {
        setIsScrolled(false);
      }
    };
    window.addEventListener("scroll", handleScroll);
    return () => window.removeEventListener("scroll", handleScroll);
  }, []);

  const toggleMenu = () => {
    setIsMenuOpen((prev) => !prev);
  };

  const closeMenu = () => {
    setIsMenuOpen(false);
  };

  const handleLoginSuccess = async (credentialResponse) => {
    try {
      const apiUrl = import.meta.env.VITE_API_URL || "http://localhost:5001/api";
      const res = await fetch(`${apiUrl}/auth/google`, {
        method: "POST",
        headers: { "Content-Type": "application/json" },
        credentials: "include",
        body: JSON.stringify({ credential: credentialResponse.credential }),
      });
      const data = await res.json();
      if (data.user) {
        login(data.user);
        closeMenu();
      }
    } catch (error) {
      console.error("Login failed", error);
    }
  };

  const handleLogout = async () => {
    await logout();
    closeMenu();
  };

  return (
    <nav className={`navbar ${isScrolled ? "scrolled" : ""}`}>
      <div className="navbar-container">
        <div className="logo">
          <Link to="/" onClick={closeMenu}>
            <img src={logo} alt="logo" />
          </Link>
        </div>

        {/* Mobile Hamburger Toggle Button */}
        <button
          className="mobile-menu-toggle"
          onClick={toggleMenu}
          aria-label={isMenuOpen ? "Close navigation menu" : "Open navigation menu"}
          aria-expanded={isMenuOpen}
        >
          {isMenuOpen ? <X size={24} /> : <Menu size={24} />}
        </button>

        {/* Navigation Content Wrapper */}
        <div className={`nav-content-wrapper ${isMenuOpen ? "is-open" : ""}`}>
          <div className="nav-button">
            <ul className="nav-links">
              <li>
                <Link to="/upload-resume" onClick={closeMenu}>
                  Resume Analyzer
                </Link>
              </li>
              <li>
                <Link to="/generate-resume" onClick={closeMenu}>
                  Generate Resume
                </Link>
              </li>
              <li>
                <a href="/about-ats.html" onClick={closeMenu}>
                  ATS
                </a>
              </li>
            </ul>
          </div>

          <div className="buttons">
            {user ? (
              <>
                <button
                  className="login-personal"
                  onClick={() => {
                    navigate("/dashboard");
                    closeMenu();
                  }}
                >
                  Dashboard
                </button>
                <button className="register" onClick={handleLogout}>
                  Logout
                </button>
              </>
            ) : (
              <div className="auth-buttons-wrapper">
                <div className="google-login-wrapper">
                  <GoogleLogin
                    onSuccess={handleLoginSuccess}
                    onError={() => console.error("Login failed from Google button")}
                    theme="outline"
                    size="large"
                    text="signin_with"
                    shape="rectangular"
                    width="220"
                    locale="en"
                    logo_alignment="left"
                  />
                </div>
              </div>
            )}
          </div>
        </div>
      </div>
    </nav>
  );
}

export default Navbar;

import React, { useState } from 'react';
import {
  User,
  GraduationCap,
  Briefcase,
  FolderGit2,
  Cpu,
  FileBadge,
  Trophy,
  Users,
  Gamepad,
  Globe,
  Heart,
  Plus,
  Trash2,
  ChevronDown,
  ChevronUp,
  Layers,
} from 'lucide-react';
import FormField from './FormField';
import TagInput from './TagInput';
import SectionOrderManager from './SectionOrderManager';

/**
 * ResumeForm Component
 * Renders the form on the left column using a clean accordion design to prevent infinite scrolling.
 * Supports add/remove operations on all lists, form validation, and character counters.
 */
export default function ResumeForm({
  data,
  updatePersonalInfo,
  // Education
  addEducation,
  updateEducation,
  removeEducation,
  // Experience
  addExperience,
  updateExperience,
  removeExperience,
  // Projects
  addProject,
  updateProject,
  removeProject,
  // Skills
  updateSkills,
  // Certifications
  addCertification,
  updateCertification,
  removeCertification,
  // Achievements
  addAchievement,
  updateAchievement,
  removeAchievement,
  // Positions of Responsibility
  addPosition,
  updatePosition,
  removePosition,
  // Extracurriculars
  addExtracurricular,
  updateExtracurricular,
  removeExtracurricular,
  // Languages
  addLanguage,
  updateLanguage,
  removeLanguage,
  // Interests
  updateInterests,
  // Section Order
  sectionOrder,
  updateSectionOrder,
  resetSectionOrder,
  // Clear button
  clearForm,
}) {
  // State to track open/closed state of accordion sections
  const [activeSections, setActiveSections] = useState({
    personalInfo: true, // open by default
    sectionOrder: false,
    skills: false,
    experience: false,
    projects: false,
    education: false,
    certifications: false,
    achievements: false,
    positions: false,
    extracurriculars: false,
    languages: false,
    interests: false,
  });

  const toggleSection = (section) => {
    setActiveSections((prev) => ({
      ...prev,
      [section]: !prev[section],
    }));
  };

  const personalInfo = data.personalInfo || {};
  const education = data.education || [];
  const experience = data.experience || [];
  const projects = data.projects || [];
  const skills = data.skills || {};
  const certifications = data.certifications || [];
  const achievements = data.achievements || [];
  const positions = data.positions || [];
  const extracurriculars = data.extracurriculars || [];
  const languages = data.languages || [];
  const interests = data.interests || [];

  return (
    <div className="resume-form-wrapper">
      <div className="form-action-header">
        <h2 className="form-header-title">Resume Details</h2>
        <button
          type="button"
          onClick={clearForm}
          className="btn btn-secondary btn-small reset-form-btn"
        >
          Clear Form
        </button>
      </div>

      <form onSubmit={(e) => e.preventDefault()} className="resume-form-element">
        {/* ==================== 1. PERSONAL INFORMATION ==================== */}
        <div className={`accordion-item ${activeSections.personalInfo ? 'active' : ''}`}>
          <button
            type="button"
            className="accordion-header"

            onClick={() => toggleSection('personalInfo')}
          >
            <div className="accordion-title-group">
              <User size={18} className="accordion-icon" />
              <span>Personal Information</span>
            </div>
            {activeSections.personalInfo ? <ChevronUp size={18} /> : <ChevronDown size={18} />}
          </button>

          <div className="accordion-content">
            <div className="form-grid">
              <FormField
                label="Full Name"
                name="fullName"
                value={personalInfo.fullName}
                onChange={(e) => updatePersonalInfo('fullName', e.target.value)}
                required
              />
              <FormField
                label="Professional Title"
                name="professionalTitle"
                value={personalInfo.professionalTitle}
                onChange={(e) => updatePersonalInfo('professionalTitle', e.target.value)}

                required
              />
              <FormField
                label="Email"
                name="email"
                type="email"
                value={personalInfo.email}
                onChange={(e) => updatePersonalInfo('email', e.target.value)}

                required
              />
              <FormField
                label="Phone Number"
                name="phone"
                type="tel"
                value={personalInfo.phone}
                onChange={(e) => updatePersonalInfo('phone', e.target.value)}

                required
              />
              <FormField
                label="LinkedIn URL"
                name="linkedin"
                value={personalInfo.linkedin}
                onChange={(e) => updatePersonalInfo('linkedin', e.target.value)}

              />
              <FormField
                label="GitHub URL"
                name="github"
                value={personalInfo.github}
                onChange={(e) => updatePersonalInfo('github', e.target.value)}

              />
              <FormField
                label="Portfolio Website"
                name="portfolio"
                value={personalInfo.portfolio}
                onChange={(e) => updatePersonalInfo('portfolio', e.target.value)}

              />
              <FormField
                label="City"
                name="city"
                value={personalInfo.city}
                onChange={(e) => updatePersonalInfo('city', e.target.value)}

              />
              <FormField
                label="State"
                name="state"
                value={personalInfo.state}
                onChange={(e) => updatePersonalInfo('state', e.target.value)}
              />
              <FormField
                label="Country"
                name="country"
                value={personalInfo.country}
                onChange={(e) => updatePersonalInfo('country', e.target.value)}
              />
            </div>

            <FormField
              label="Professional Summary"
              name="summary"
              type="textarea"
              value={personalInfo.summary}
              onChange={(e) => updatePersonalInfo('summary', e.target.value)}
              maxLength={500}
              rows={4}
              required
            />
          </div>
        </div>

        {/* ==================== RESUME SECTION ORDER ==================== */}
        <div className={`accordion-item ${activeSections.sectionOrder ? 'active' : ''}`}>
          <button
            type="button"
            className="accordion-header"
            onClick={() => toggleSection('sectionOrder')}
          >
            <div className="accordion-title-group">
              <Layers size={18} className="accordion-icon" />
              <span>Resume Section Order</span>
            </div>
            {activeSections.sectionOrder ? <ChevronUp size={18} /> : <ChevronDown size={18} />}
          </button>

          {activeSections.sectionOrder && (
            <div className="accordion-content">
              <SectionOrderManager
                sectionOrder={sectionOrder}
                onChangeOrder={updateSectionOrder}
                onResetOrder={resetSectionOrder}
                data={data}
              />
            </div>
          )}
        </div>

        {/* ==================== 2. SKILLS CATEGORIES ==================== */}
        <div className={`accordion-item ${activeSections.skills ? 'active' : ''}`}>
          <button
            type="button"
            className="accordion-header"
            onClick={() => toggleSection('skills')}
          >
            <div className="accordion-title-group">
              <Cpu size={18} className="accordion-icon" />
              <span>Skills Categories</span>
              {Object.values(skills).some((arr) => arr.length > 0) && (
                <span className="section-badge-count">Filled</span>
              )}
            </div>
            {activeSections.skills ? <ChevronUp size={18} /> : <ChevronDown size={18} />}
          </button>

          <div className="accordion-content">
            <div className="skills-form-grid">
              <TagInput
                label="Programming Languages"
                tags={skills.languages}
                onChange={(newTags) => updateSkills('languages', newTags)}
                placeholder="e.g. JavaScript, Python, Go, Java"
              />
              <TagInput
                label="Frameworks & Libraries"
                tags={skills.frameworks}
                onChange={(newTags) => updateSkills('frameworks', newTags)}
                placeholder="e.g. React, Next.js, Node.js, Vue"
              />
              <TagInput
                label="Databases"
