            </h2>
            <ul style={{ margin: '0', paddingLeft: '18px', fontSize: '10pt', color: '#111111', listStyleType: 'disc' }}>
              {achievements.map((ach, index) => (
                <li key={index} style={{ marginBottom: '2px' }}>
                  {typeof ach === 'string' ? ach : ach.text || ''}
