import React, { useState } from 'react';
import { GripVertical, RotateCcw, ChevronUp, ChevronDown } from 'lucide-react';
import { DEFAULT_SECTION_ORDER, SECTION_META } from '../constants/sectionOrder';
import './SectionOrderManager.css';

export default function SectionOrderManager({
  sectionOrder = DEFAULT_SECTION_ORDER,
  onChangeOrder,
  onResetOrder,
  data = {},
}) {
  const [draggedIndex, setDraggedIndex] = useState(null);

  // Helper to check if a section currently has content in resumeData
  const hasContent = (key) => {
    switch (key) {
      case 'summary':
        return Boolean(data.personalInfo?.summary);
      case 'skills':
        return Object.values(data.skills || {}).some((arr) => arr && arr.length > 0);
      case 'experience':
        return Boolean(data.experience && data.experience.length > 0);
      case 'projects':
        return Boolean(data.projects && data.projects.length > 0);
      case 'education':
        return Boolean(data.education && data.education.length > 0);
      case 'certifications':
        return Boolean(data.certifications && data.certifications.length > 0);
      case 'achievements':
        return Boolean(data.achievements && data.achievements.length > 0);
      case 'positions':
        return Boolean(data.positions && data.positions.length > 0);
      case 'extracurriculars':
        return Boolean(data.extracurriculars && data.extracurriculars.length > 0);
      case 'languages':
        return Boolean(data.languages && data.languages.length > 0);
      case 'interests':
        return Boolean(data.interests && data.interests.length > 0);
      default:
        return false;
    }
  };

  const handleDragStart = (e, index) => {
    setDraggedIndex(index);
    e.dataTransfer.effectAllowed = 'move';
    e.dataTransfer.setData('text/plain', index.toString());
  };

  const handleDragOver = (e) => {
    e.preventDefault();
    e.dataTransfer.dropEffect = 'move';
  };

  const handleDrop = (e, targetIndex) => {
    e.preventDefault();
    if (draggedIndex === null || draggedIndex === targetIndex) return;

    const newOrder = [...sectionOrder];
    const [draggedItem] = newOrder.splice(draggedIndex, 1);
    newOrder.splice(targetIndex, 0, draggedItem);

    onChangeOrder(newOrder);
    setDraggedIndex(null);
  };

  const handleDragEnd = () => {
    setDraggedIndex(null);
  };

  const moveUp = (index) => {
    if (index === 0) return;
    const newOrder = [...sectionOrder];
    const [item] = newOrder.splice(index, 1);
    newOrder.splice(index - 1, 0, item);
    onChangeOrder(newOrder);
  };

  const moveDown = (index) => {
    if (index === sectionOrder.length - 1) return;
    const newOrder = [...sectionOrder];
    const [item] = newOrder.splice(index, 1);
    newOrder.splice(index + 1, 0, item);
    onChangeOrder(newOrder);
  };

  return (
    <div className="section-order-container">
      <div className="section-order-header">
        <span className="section-order-subtitle">
          Drag cards or use arrows to rearrange section order on your resume.
        </span>
        <button
          type="button"
          className="btn-reset-order"
          onClick={onResetOrder}
          title="Reset to default order"
        >
          <RotateCcw size={14} />
          <span>Reset Order</span>
        </button>
      </div>

      <div className="section-order-list">
        {sectionOrder.map((key, index) => {
          const meta = SECTION_META[key] || { label: key };
          const active = hasContent(key);

          return (
            <div
              key={key}
              className={`section-order-card ${draggedIndex === index ? 'dragging' : ''}`}
              draggable
              onDragStart={(e) => handleDragStart(e, index)}
              onDragOver={handleDragOver}
              onDrop={(e) => handleDrop(e, index)}
              onDragEnd={handleDragEnd}
            >
              <div className="card-drag-handle" title="Drag to reorder">
                <GripVertical size={18} />
              </div>

              <div className="card-info">
                <span className="card-number">{index + 1}</span>
                <span className="card-label">{meta.label}</span>
              </div>

              <div className="card-actions">
                <span className={`content-badge ${active ? 'badge-active' : 'badge-empty'}`}>
                  {active ? 'Active' : 'Empty'}
                </span>

                <div className="arrow-controls">
                  <button
                    type="button"
                    className="btn-arrow"
                    onClick={() => moveUp(index)}
                    disabled={index === 0}
                    title="Move section up"
                  >
                    <ChevronUp size={14} />
                  </button>
                  <button
                    type="button"
                    className="btn-arrow"
                    onClick={() => moveDown(index)}
                    disabled={index === sectionOrder.length - 1}
                    title="Move section down"
                  >
                    <ChevronDown size={14} />
                  </button>
                </div>
              </div>
            </div>
          );
        })}
      </div>
    </div>
  );
}

import { useState } from 'react';
import { X } from 'lucide-react';

/**
 * TagInput Component
 * Allows entering tags (for skills, interests) with Enter, comma, or blur.
 * Features automatic deduplication and simple tag deletion.
 */
export default function TagInput({
  label,
  tags = [],
  onChange,
  placeholder = 'Type and press Enter or comma',
  required = false,
  error = '',
  className = '',
}) {
  const [inputValue, setInputValue] = useState('');

  const addTag = (value) => {
    const trimmed = value.trim();
    if (!trimmed) return;

    // Check if tag already exists (case-insensitive check)
    const exists = tags.some((t) => t.toLowerCase() === trimmed.toLowerCase());
    if (!exists) {
      const updatedTags = [...tags, trimmed];
      onChange(updatedTags);
    }
    setInputValue('');
  };

  const handleKeyDown = (e) => {
    if (e.key === 'Enter') {
      e.preventDefault();
      addTag(inputValue);
    } else if (e.key === ',') {
      e.preventDefault();
      addTag(inputValue);
    }
  };

  const handleBlur = () => {
    addTag(inputValue);
  };

  const removeTag = (indexToRemove) => {
    const updatedTags = tags.filter((_, idx) => idx !== indexToRemove);
    onChange(updatedTags);
  };

  return (
    <div className={`tag-input-container ${className}`}>
      {label && (
        <div className="tag-input-header">
          <label className="tag-input-label">
            {label}
            {required && tags.length === 0 && <span className="required-indicator" aria-hidden="true"> *</span>}
          </label>
          {required && tags.length === 0 && (
            <span className="tag-required-hint">At least one required</span>
          )}
        </div>
      )}

      <div className="tag-input-wrapper">
        <div className="tags-list">
          {tags.map((tag, index) => (
            <span key={index} className="tag-badge">
              <span className="tag-text">{tag}</span>
              <button
                type="button"
                onClick={() => removeTag(index)}
                className="tag-remove-button"
                aria-label={`Remove tag ${tag}`}
              >
                <X size={12} />
              </button>
            </span>
          ))}
          <input
            type="text"
            value={inputValue}
            onChange={(e) => setInputValue(e.target.value)}
            onKeyDown={handleKeyDown}
            onBlur={handleBlur}
            placeholder={tags.length === 0 ? placeholder : 'Add more...'}
            className="tag-raw-input"
          />
        </div>
      </div>
      {error && <p className="form-field-error-message" role="alert">{error}</p>}
    </div>
  );
}

