import { useState, useRef, useEffect } from 'react';
import { Download, AlertCircle } from 'lucide-react';
import ResumeForm from '../components/ResumeForm';
import ResumePreview from '../components/ResumePreview';
import { DEFAULT_SECTION_ORDER } from '../constants/sectionOrder';
import { useAuth } from '../lib/AuthContext';
import logo from "../assets/logo.png";

import './GenerateResume.css';

// Initial state for the resume data, starts completely empty as per requirements
const initialResumeData = {
  personalInfo: {
    fullName: '',
    professionalTitle: '',
    email: '',
    phone: '',
    linkedin: '',
    github: '',
    portfolio: '',
    city: '',
    state: '',
    country: '',
    summary: '',
  },
  education: [],
  experience: [],
  projects: [],
  skills: {
    languages: [],
    frameworks: [],
    databases: [],
    tools: [],
    cloud: [],
    other: [],
  },
  certifications: [],
  achievements: [],
  positions: [],
  extracurriculars: [],
  languages: [],
  interests: [],
};

export default function App() {
  const { user } = useAuth();
  const [draftId, setDraftId] = useState(null);
  const [saveStatus, setSaveStatus] = useState('');
  const [isInitializing, setIsInitializing] = useState(true);

  // Central Resume State
  const [resumeData, setResumeData] = useState(initialResumeData);
  const [sectionOrder, setSectionOrder] = useState(DEFAULT_SECTION_ORDER);

  // Fetch initial draft
  useEffect(() => {
    if (user) {
      const fetchDraft = async () => {
        try {
          const apiUrl = import.meta.env.VITE_API_URL || "http://localhost:5001/api";
          const res = await fetch(`${apiUrl}/resume-drafts`, {
            credentials: 'include'
          });
          if (res.ok) {
            const drafts = await res.json();
            if (drafts.length > 0) {
              setDraftId(drafts[0]._id);
              const fetchedData = drafts[0].resumeData || initialResumeData;
              setResumeData(fetchedData);
              if (fetchedData.sectionOrder && fetchedData.sectionOrder.length > 0) {
                setSectionOrder(fetchedData.sectionOrder);
              }
            }
          }
        } catch (error) {
          console.error("Error fetching draft", error);
        } finally {
          setIsInitializing(false);
        }
      };
      fetchDraft();
    } else {
      // Avoid calling setState synchronously within an effect to prevent cascading renders
      // Schedule the state update asynchronously
      setTimeout(() => setIsInitializing(false), 0);
    }
  }, [user]);

  // Debounced auto-save
  useEffect(() => {
    if (isInitializing || !user) return;

    const timeoutId = setTimeout(async () => {
      setSaveStatus('Saving...');
      try {
        const apiUrl = import.meta.env.VITE_API_URL || "http://localhost:5001/api";
        const url = draftId ? `${apiUrl}/resume-drafts/${draftId}` : `${apiUrl}/resume-drafts`;
        const method = draftId ? 'PUT' : 'POST';

        const res = await fetch(url, {
          method,
          headers: { 'Content-Type': 'application/json' },
          credentials: 'include',
          body: JSON.stringify({ resumeData, title: 'My Resume' })
        });

        if (res.ok) {
          const data = await res.json();
          if (!draftId) setDraftId(data._id);
          setSaveStatus('');
        } else {
          setSaveStatus('Error saving');
        }
      } catch (error) {
        console.error("Error saving draft", error);
        setSaveStatus('Error saving');
      }
    }, 1000);

    return () => clearTimeout(timeoutId);
  }, [resumeData, user, draftId, isInitializing]);


  // PDF Generation loading state
  const [isGeneratingPdf, setIsGeneratingPdf] = useState(false);
  const [pdfError, setPdfError] = useState('');

  // Ref to target the print container
  const previewRef = useRef(null);

  // State update handlers
  const updatePersonalInfo = (field, value) => {
    setResumeData((prev) => ({
      ...prev,
      personalInfo: {
        ...prev.personalInfo,
        [field]: value,
      },
    }));
  };

  // Education Helpers
  const addEducation = () => {
    setResumeData((prev) => ({
      ...prev,
      education: [
        ...prev.education,
        { college: '', degree: '', branch: '', cgpa: '', startYear: '', endYear: '' },
      ],
    }));
  };

  const updateEducation = (index, field, value) => {
    setResumeData((prev) => {
      const updated = [...prev.education];
      updated[index] = { ...updated[index], [field]: value };
      return { ...prev, education: updated };
    });
  };

  const removeEducation = (index) => {
    setResumeData((prev) => ({
      ...prev,
      education: prev.education.filter((_, idx) => idx !== index),
    }));
  };

  // Experience Helpers
  const addExperience = () => {
    setResumeData((prev) => ({
      ...prev,
      experience: [
        ...prev.experience,
        { company: '', title: '', location: '', startDate: '', endDate: '', currentlyWorking: false, description: '' },
      ],
    }));
  };

  const updateExperience = (index, field, value) => {
    setResumeData((prev) => {
      const updated = [...prev.experience];
      if (field === 'currentlyWorking') {
        updated[index] = {
          ...updated[index],
          currentlyWorking: value,
          endDate: value ? '' : updated[index].endDate, // Clear end date if currently working
        };
      } else {
        updated[index] = { ...updated[index], [field]: value };
      }
      return { ...prev, experience: updated };
    });
  };

  const removeExperience = (index) => {
    setResumeData((prev) => ({
      ...prev,
      experience: prev.experience.filter((_, idx) => idx !== index),
    }));
  };

  // Projects Helpers
  const addProject = () => {
    setResumeData((prev) => ({
      ...prev,
      projects: [
        ...prev.projects,
        { name: '', techStack: '', githubLink: '', liveDemoLink: '', description: '', achievements: '' },
      ],
    }));
  };

  const updateProject = (index, field, value) => {
    setResumeData((prev) => {
      const updated = [...prev.projects];
      updated[index] = { ...updated[index], [field]: value };
      return { ...prev, projects: updated };
    });
  };

  const removeProject = (index) => {
    setResumeData((prev) => ({
      ...prev,
      projects: prev.projects.filter((_, idx) => idx !== index),
    }));
  };

  // Skills Categories
  const updateSkills = (category, newTags) => {
    setResumeData((prev) => ({
      ...prev,
      skills: {
        ...prev.skills,
        [category]: newTags,
      },
    }));
  };

  // Certifications Helpers
  const addCertification = () => {
    setResumeData((prev) => ({
      ...prev,
      certifications: [
        ...prev.certifications,
        { name: '', org: '', date: '', url: '' },
      ],
    }));
  };

  const updateCertification = (index, field, value) => {
    setResumeData((prev) => {
      const updated = [...prev.certifications];
      updated[index] = { ...updated[index], [field]: value };
      return { ...prev, certifications: updated };
    });
  };

  const removeCertification = (index) => {
    setResumeData((prev) => ({
      ...prev,
      certifications: prev.certifications.filter((_, idx) => idx !== index),
    }));
  };

  // Achievements Helpers
  const addAchievement = () => {
    setResumeData((prev) => ({
      ...prev,
      achievements: [...prev.achievements, ''],
    }));
  };

  const updateAchievement = (index, value) => {
    setResumeData((prev) => {
      const updated = [...prev.achievements];
      updated[index] = value;
      return { ...prev, achievements: updated };
    });
  };

  const removeAchievement = (index) => {
    setResumeData((prev) => ({
      ...prev,
      achievements: prev.achievements.filter((_, idx) => idx !== index),
    }));
  };

  // Positions Helpers
  const addPosition = () => {
    setResumeData((prev) => ({
      ...prev,
      positions: [
        ...prev.positions,
        { role: '', org: '', duration: '', description: '' },
      ],
    }));
  };

  const updatePosition = (index, field, value) => {
    setResumeData((prev) => {
      const updated = [...prev.positions];
      updated[index] = { ...updated[index], [field]: value };
      return { ...prev, positions: updated };
    });
  };

  const removePosition = (index) => {
    setResumeData((prev) => ({
      ...prev,
      positions: prev.positions.filter((_, idx) => idx !== index),
    }));
  };

  // Extracurriculars Helpers
  const addExtracurricular = () => {
    setResumeData((prev) => ({
      ...prev,
      extracurriculars: [...prev.extracurriculars, ''],
    }));
  };

  const updateExtracurricular = (index, value) => {
    setResumeData((prev) => {
      const updated = [...prev.extracurriculars];
      updated[index] = value;
      return { ...prev, extracurriculars: updated };
    });
  };

  const removeExtracurricular = (index) => {
    setResumeData((prev) => ({
      ...prev,
      extracurriculars: prev.extracurriculars.filter((_, idx) => idx !== index),
    }));
  };

  // Languages Helpers
  const addLanguage = () => {
    setResumeData((prev) => ({
      ...prev,
      languages: [
        ...prev.languages,
        { name: '', proficiency: '' },
      ],
    }));
  };

  const updateLanguage = (index, field, value) => {
    setResumeData((prev) => {
      const updated = [...prev.languages];
      updated[index] = { ...updated[index], [field]: value };
      return { ...prev, languages: updated };
    });
  };

  const removeLanguage = (index) => {
    setResumeData((prev) => ({
      ...prev,
      languages: prev.languages.filter((_, idx) => idx !== index),
    }));
  };

  // Interests Tags
  const updateInterests = (newTags) => {
    setResumeData((prev) => ({
      ...prev,
      interests: newTags,
    }));
  };

  // Section Order Handlers
  const updateSectionOrder = (newOrder) => {
    setSectionOrder(newOrder);
    setResumeData((prev) => ({
      ...prev,
      sectionOrder: newOrder,
    }));
  };

  const resetSectionOrder = () => {
    setSectionOrder(DEFAULT_SECTION_ORDER);
    setResumeData((prev) => ({
      ...prev,
      sectionOrder: DEFAULT_SECTION_ORDER,
    }));
  };

  // Clear Form handler
  const clearForm = async () => {
    if (window.confirm('Are you sure you want to clear all data? This cannot be undone.')) {
      setResumeData(initialResumeData);
      setSectionOrder(DEFAULT_SECTION_ORDER);
      if (draftId && user) {
        try {
           const apiUrl = import.meta.env.VITE_API_URL || "http://localhost:5001/api";
           await fetch(`${apiUrl}/resume-drafts/${draftId}`, {
             method: 'DELETE',
             credentials: 'include'
           });
           setDraftId(null);
        } catch (error) {
          console.error("Failed to delete draft", error);
        }
      }
    }
  };

  // PDF Generation Handler
  const downloadPdf = async () => {
    const fullName = resumeData.personalInfo.fullName?.trim() || 'Resume';
    const element = previewRef.current;
    if (!element) {
      setPdfError('Preview content not found.');
      return;
    }

    setIsGeneratingPdf(true);
    setPdfError('');

    try {
      // Import dependencies dynamically to avoid SSR or bundle footprint issues
      const html2canvas = (await import('html2canvas')).default;
      const { jsPDF } = await import('jspdf');

      // Create a duplicate/style element context to avoid container scale scaling
      // We will clone the preview container and render it off-screen at full size
      const originalWidth = element.style.width;
      const originalTransform = element.style.transform;

      // Temporarily reset scaling for html2canvas to render accurately
      element.style.transform = 'scale(1)';
      element.style.width = '8.27in'; // Force actual standard width

      // Scroll to top of preview so canvas handles offsets correctly
      const scrollPos = element.scrollTop;
      element.scrollTop = 0;

      // Render the element to canvas
      const canvas = await html2canvas(element, {
        scale: 2.5, // Increase scale for high resolution print
        useCORS: true,
        logging: false,
        backgroundColor: '#ffffff',
      });

      // Restore styling properties
      element.style.transform = originalTransform;
      element.style.width = originalWidth;
      element.scrollTop = scrollPos;

      // Page calculations
      const imgWidth = 210; // A4 standard width in mm
      const pageHeight = 297; // A4 standard height in mm
      const imgHeight = (canvas.height * imgWidth) / canvas.width;
      let heightLeft = imgHeight;
      let position = 0;

      const pdf = new jsPDF('p', 'mm', 'a4');
      const imgData = canvas.toDataURL('image/png');

      pdf.addImage(imgData, 'PNG', 0, position, imgWidth, imgHeight, undefined, 'FAST');
      heightLeft -= pageHeight;

      while (heightLeft > 0) {
        position = heightLeft - imgHeight;
        pdf.addPage();
        pdf.addImage(imgData, 'PNG', 0, position, imgWidth, imgHeight, undefined, 'FAST');
        heightLeft -= pageHeight;
      }

      const filename = `${fullName.replace(/\s+/g, '_')}_Resume.pdf`;
      pdf.save(filename);

    } catch (err) {
      console.error('PDF Generation Error:', err);
      setPdfError('An error occurred while generating the PDF. Please try again.');
    } finally {
      setIsGeneratingPdf(false);
    }
  };

  return (
    <div className="app-container">
      {/* Header bar */}
      <header className="app-header glass-panel">

        <div className="brand-section">
            <div className="logo">
              <img src={logo} alt="logo" />
            </div>

          <h1 className="brand-name">Resume Builder</h1>
        </div>

      </header>

      {/* Main Form + Preview Workspace */}
      <main className="workspace-grid">
        {/* Left Side (40%) - Form */}
        <section className="form-column">
          <ResumeForm
            data={resumeData}
            updatePersonalInfo={updatePersonalInfo}
            addEducation={addEducation}
            updateEducation={updateEducation}
            removeEducation={removeEducation}
            addExperience={addExperience}
            updateExperience={updateExperience}
            removeExperience={removeExperience}
            addProject={addProject}
            updateProject={updateProject}
            removeProject={removeProject}
            updateSkills={updateSkills}
            addCertification={addCertification}
            updateCertification={updateCertification}
            removeCertification={removeCertification}
            addAchievement={addAchievement}
            updateAchievement={updateAchievement}
            removeAchievement={removeAchievement}
            addPosition={addPosition}
            updatePosition={updatePosition}
            removePosition={removePosition}
            addExtracurricular={addExtracurricular}
            updateExtracurricular={updateExtracurricular}
            removeExtracurricular={removeExtracurricular}
            addLanguage={addLanguage}
            updateLanguage={updateLanguage}
            removeLanguage={removeLanguage}
            updateInterests={updateInterests}
            sectionOrder={sectionOrder}
            updateSectionOrder={updateSectionOrder}
            resetSectionOrder={resetSectionOrder}
            clearForm={clearForm}
          />
        </section>

        {/* Right Side (60%) - Sticky Preview & Score Dashboard */}
        <section className="preview-column">
          {/* Sticky Controls */}
          <div className="preview-sticky-control glass-panel">
            <div className="preview-controls-left">
              <h3>Live Resume Preview</h3>
              {saveStatus && (
                <span className={`save-status ${saveStatus.includes('Error') ? 'error' : ''}`} style={{ fontSize: '0.85rem', color: saveStatus === 'Saved' ? 'var(--success-color, #10b981)' : 'var(--text-secondary, #64748b)' }}>
                  {saveStatus}
                </span>
              )}
            </div>

            <button
              onClick={downloadPdf}
              disabled={isGeneratingPdf}
              className="btn btn-primary"
            >
              {isGeneratingPdf ? (
                <>
                  <span className="spinner" />
                  <span>Generating PDF...</span>
                </>
              ) : (
                <>
                  <Download size={18} />
                  <span>Download Resume (PDF)</span>
                </>
              )}
            </button>
          </div>

          {pdfError && (
            <div className="warning-item critical">
              <AlertCircle size={16} />
              <span>{pdfError}</span>
            </div>
          )}

          {/* Live Print-Friendly Preview */}
          <ResumePreview data={resumeData} previewRef={previewRef} sectionOrder={sectionOrder} />
        </section>
      </main>
    </div>
  );
}

