/* RESPONSIVE DESIGN */
@media (max-width: 640px) {
  .profile-form-wrapper {
    margin-top: 75px;
    padding: 0 1rem 2rem 1rem;
  }

  .personal-row {
    flex-direction: column;
    align-items: center;
    text-align: center;
  }

  .personal-inputs {
    width: 100%;
  }

  .form-actions-bottom {
    flex-direction: column;
    align-items: stretch;
  }

